  /* ---------- 5. Словник: пояснення термінів простими словами ----------
     Клієнт питає «що таке бекенд?», «нащо сервер?» — бот коротко пояснює,
     що це і навіщо саме йому. Не вчимо робити сайти, лише знімаємо страх.   */
  const Q_UA = ["що таке ", "а що таке ", "що це ", "що значить ", "що означає ", "навіщо ", "нащо ", "для чого ", "поясніть ", "поясни ", "не розумію "];
  const Q_RU = ["что такое ", "а что такое ", "что значит ", "что означает ", "зачем ", "для чего ", "объясните ", "объясни ", "не понимаю "];
  function gl(id, title, aliases, text, next) {
    const keys = [];
    aliases.forEach(a => {
      Q_UA.concat(Q_RU).forEach(q => keys.push(q + a));
      keys.push(a + " це", a + " это", a + " що це", a + " что это", "what is " + a);
      if (a.length >= 5) keys.push(a);
    });
    return { id: "g_" + id, title, keys, text, next: next || ["menu"], glossary: true };
  }
